 static void RequestMode(){using(var mutex=new Mutex(false,"Local\\FireflyMode-"+RuntimeManager.Key)){bool held=false;try{try{held=mutex.WaitOne(3000);}catch(AbandonedMutexException){held=true;}if(!held)return;Directory.CreateDirectory(RuntimeManager.Data);string f=Path.Combine(RuntimeManager.Data,"display-mode.json"),tmp=f+"."+Process.GetCurrentProcess().Id+".tmp";File.WriteAllText(tmp,RuntimeManager.Json.Serialize(new{mode=Mode,at=DateTime.UtcNow.ToString("o")}));if(File.Exists(f))File.Replace(tmp,f,null);else File.Move(tmp,f);}finally{if(held)mutex.ReleaseMutex();}}}
