 static void StartChat(){if(ChatBusy){Web.CoreWebView2.PostWebMessageAsJson("{\"notice\":\"\u7b49\u8fd9\u5c01\u56de\u4fe1\u5199\u5b8c\uff0c\u518d\u5c55\u5f00\u5427\u3002\"}");return;}OpenPeer(false);PublishState();}
 static void SwitchToPet(){if(ChatBusy)return;RestorePetOnClose=false;OpenPeer(true);PublishState();}
 static void OpenPeer(bool pet){var info=new ProcessStartInfo(Path.Combine(RuntimeManager.Root,pet?"Firefly-Pet.exe":"Firefly.exe"),pet?"--from-chat":"--from-pet"){UseShellExecute=false,WorkingDirectory=RuntimeManager.Root};info.EnvironmentVariables["FIREFLY_DATA_DIR"]=RuntimeManager.Data;try{var child=Process.Start(info);BootDiagnostics.Record("peer-start","mode="+(pet?"pet":"chat")+" pid="+child.Id);child.EnableRaisingEvents=true;child.Exited+=(s,e)=>{BootDiagnostics.Record("peer-launch-exit","pid="+child.Id+" code=0x"+unchecked((uint)child.ExitCode).ToString("X8"));};}catch(Exception ex){BootDiagnostics.Record("peer-start-failed",ex.GetType().Name);ShowOwnWindow();Forms.MessageBox.Show("另一个窗口暂时没有打开，当前窗口已保留。","流萤");}}
 static void NotifyPeer(string command){string name="Firefly-window-"+RuntimeManager.Key+"-"+(Pet?"chat":"pet");try{using(var client=new NamedPipeClientStream(".",name,PipeDirection.Out)){client.Connect(150);using(var writer=new StreamWriter(client)){writer.WriteLine(command);}}}catch(TimeoutException){}catch(IOException){}}
 static void HandleWindowCommand(string command){
  if(command=="show"||command=="show-from-pet"||command=="show-from-chat"){if(command=="show-from-pet")RestorePetOnClose=true;RequestMode();ShowOwnWindow();NotifyPeer("hide-if-other-mode");}
  if(command=="close-for-update"){ClosingForUpdate=true;Win.Close();}
  if(command=="hide"||(command=="hide-if-other-mode"&&!OwnCurrentMode()))Win.Hide();
  if(command=="topmost"){Win.Topmost=!Win.Topmost;Save();RuntimeManager.Log("window-pet","topmost="+Win.Topmost);}
  if(command=="scale-up")Scale(1.1);if(command=="scale-down")Scale(.9);PublishState();
 }
 static void StartPipe(){Task.Run(()=>{try{while(!Quitting){var security=new PipeSecurity();security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var server=new NamedPipeServerStream(PipeName,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,1024,1024,security)){Pipe=server;server.WaitForConnection();using(var reader=new StreamReader(server,System.Text.Encoding.UTF8,true,1024,true)){string command=reader.ReadLine();if(command!=null&&command.Length<64){Win.Dispatcher.Invoke(new Action(()=>HandleWindowCommand(command)));try{using(var writer=new StreamWriter(server,System.Text.Encoding.UTF8,1024,true)){writer.AutoFlush=true;writer.WriteLine("OK mode="+Mode);}}catch(IOException){} }}}}}catch(Exception e){if(!Quitting)RuntimeManager.Log("window-"+Mode,"pipe "+e.GetType().Name);}});}

 static void PublishState(){if(Win==null)return;try{Directory.CreateDirectory(RuntimeManager.Data);string file=Path.Combine(RuntimeManager.Data,"window-"+Mode+"-state.json"),tmp=file+"."+Process.GetCurrentProcess().Id+".tmp";File.WriteAllText(tmp,RuntimeManager.Json.Serialize(new{pid=Process.GetCurrentProcess().Id,mode=Mode,visible=Win.IsVisible,corePID=Entry==null?0:Entry.pid,width=Win.Width,height=Win.Height,left=Win.Left,top=Win.Top,topmost=Win.Topmost,trayVisible=Tray!=null&&Tray.Visible,workingSet=Process.GetCurrentProcess().WorkingSet64,at=DateTime.UtcNow.ToString("o")}));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);}catch{}}
 static Forms.ToolStripMenuItem Item(string title,Action action){var i=new Forms.ToolStripMenuItem(title);i.Click+=(s,e)=>Win.Dispatcher.BeginInvoke(action);return i;}
 static void TrayMenu(){if(Tray!=null)return;using(var source=new System.Drawing.Icon(Path.Combine(RuntimeManager.Root,"public/brand/firefly-shell-v3.ico"),32,32))using(var bitmap=source.ToBitmap()){var native=bitmap.GetHicon();try{TrayBitmapIcon=(System.Drawing.Icon)System.Drawing.Icon.FromHandle(native).Clone();}finally{DestroyIcon(native);}}Tray=new NativeTray(new WindowInteropHelper(Win).Handle,TrayBitmapIcon);var menu=TrayTheme.Create(()=>Day);menu.Items.Add(Item("打开聊天",()=>{if(Pet)StartChat();else{RequestMode();ShowOwnWindow();NotifyPeer("hide-if-other-mode");}}));menu.Items.Add(Item("打开桌宠",()=>{if(Pet){RequestMode();ShowOwnWindow();NotifyPeer("hide-if-other-mode");}else SwitchToPet();}));menu.Items.Add(Item("收起窗口",()=>{if(Tray.Visible)Win.Hide();else Win.WindowState=WindowState.Minimized;}));menu.Items.Add(new Forms.ToolStripSeparator());menu.Items.Add(Item("退出流萤",ExitApplication));Tray.ContextMenuStrip=menu;Tray.DoubleClick+=(s,e)=>Win.Dispatcher.BeginInvoke(new Action(()=>{if(Pet)StartChat();else{RequestMode();ShowOwnWindow();NotifyPeer("hide-if-other-mode");}}));Tray.Visible=true;if(!Tray.Visible)TrayFailures++;BootDiagnostics.Record("tray-created","registered="+Tray.Visible+" ownerPid="+Process.GetCurrentProcess().Id);PublishState();}

 static Brush ColorBrush(string color){return (Brush)new BrushConverter().ConvertFromString(color);}
 static ContextMenu PetMenu(){Brush paper=ColorBrush(Day?"#F8F3E7":"#102923"),ink=ColorBrush(Day?"#354D42":"#EEE7D4"),line=ColorBrush(Day?"#B7C7AF":"#80734D"),hover=ColorBrush(Day?"#E7EEDC":"#254135"),muted=ColorBrush(Day?"#788772":"#B6B18E");var menu=new ContextMenu{Foreground=ink,Background=paper,BorderBrush=line,BorderThickness=new Thickness(1),Padding=new Thickness(7),MinWidth=194,FontFamily=new FontFamily("Microsoft YaHei UI"),FontSize=13,HasDropShadow=true,OverridesDefaultStyle=true};
  var shell=new FrameworkElementFactory(typeof(Border));shell.SetValue(Border.BackgroundProperty,paper);shell.SetValue(Border.BorderBrushProperty,line);shell.SetValue(Border.BorderThicknessProperty,new Thickness(1));shell.SetValue(Border.CornerRadiusProperty,new CornerRadius(12));shell.SetValue(Border.PaddingProperty,new Thickness(7));shell.AppendChild(new FrameworkElementFactory(typeof(ItemsPresenter)));menu.Template=new ControlTemplate(typeof(ContextMenu)){VisualTree=shell};
  var template=new ControlTemplate(typeof(MenuItem));var border=new FrameworkElementFactory(typeof(Border));border.Name="entry";border.SetValue(Border.BackgroundProperty,Brushes.Transparent);border.SetValue(Border.CornerRadiusProperty,new CornerRadius(7));border.SetValue(Border.PaddingProperty,new Thickness(12,8,12,8));var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(ContentPresenter.ContentSourceProperty,"Header");border.AppendChild(content);template.VisualTree=border;var over=new Trigger{Property=MenuItem.IsHighlightedProperty,Value=true};over.Setters.Add(new Setter(Border.BackgroundProperty,hover,"entry"));template.Triggers.Add(over);
  var heading=new TextBlock{Text="流萤  ·  "+(Day?"春信":"夜信"),Foreground=muted,FontSize=11,Margin=new Thickness(12,7,12,9)};menu.Items.Add(heading);Action<string,Action> add=(title,action)=>{var item=new MenuItem{Header=title,Foreground=ink,Template=template};item.Click+=(s,e)=>action();menu.Items.Add(item);};Action separator=()=>menu.Items.Add(new Border{Height=1,Background=line,Opacity=.45,Margin=new Thickness(9,5,9,5)});
  add("展开聊天",StartChat);add("和她说句话",()=>Web.CoreWebView2.PostWebMessageAsJson("{\"composer\":true}"));add("收进托盘",()=>Win.Hide());separator();add((Win.Topmost?"✓  ":"    ")+"保持置顶",()=>{Win.Topmost=!Win.Topmost;Save();});menu.Items.Add(ScaleSlider(ink,line,hover,template));separator();add("微笑",()=>Web.CoreWebView2.PostWebMessageAsJson("{\"expression\":10}"));add("疑惑",()=>Web.CoreWebView2.PostWebMessageAsJson("{\"expression\":6}"));add("换个待机动作",()=>Web.CoreWebView2.PostWebMessageAsJson("{\"motion\":\"Tick2\"}"));separator();add("暂别桌面",()=>Win.Close());return menu;}
 static void StartDrag(){if((GetAsyncKeyState(1)&0x8000)==0)return;if(DragTimer!=null)DragTimer.Stop();CursorPoint start;if(!GetCursorPos(out start))return;double left=Win.Left,top=Win.Top;var source=HwndSource.FromHwnd(new WindowInteropHelper(Win).Handle);var transform=source.CompositionTarget.TransformFromDevice;DragTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(16)};DragTimer.Tick+=(s,e)=>{if(Quitting||(GetAsyncKeyState(1)&0x8000)==0){DragTimer.Stop();Clamp();Save();RuntimeManager.Log("window-pet","direct-drag-end");return;}CursorPoint now;if(GetCursorPos(out now)){var delta=transform.Transform(new Vector(now.X-start.X,now.Y-start.Y));Win.Left=left+delta.X;Win.Top=top+delta.Y;}};DragTimer.Start();RuntimeManager.Log("window-pet","direct-drag-start; no system outline");}
 static void TogglePassthrough(){IntPtr h=new WindowInteropHelper(Win).Handle;int style=GetWindowLong(h,-20);SetWindowLong(h,-20,style^0x20);RuntimeManager.Log("window-pet","passthrough="+((style&0x20)==0));}
 static MenuItem ScaleSlider(Brush ink,Brush line,Brush hover,ControlTemplate template){var panel=new StackPanel{Width=164};var label=new TextBlock{Text="大小  "+Math.Round(Win.Width/4)+"%",Foreground=ink,FontSize=11,Margin=new Thickness(0,3,0,6)};panel.Children.Add(label);var slider=new Slider{Minimum=60,Maximum=170,Value=Math.Max(60,Math.Min(170,Win.Width/4)),SmallChange=1,LargeChange=10,IsSnapToTickEnabled=false,Height=23,ToolTip="拖动滑杆调整大小"};
  string accent=Day?"#8BA782":"#CDBB83",track=Day?"#D8E1CB":"#405247",thumb=Day?"#FAF6E9":"#E6DCB5";
  string xaml="<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Slider'><Grid Background='Transparent'><Track x:Name='PART_Track' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{Binding Value,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}'><Track.DecreaseRepeatButton><RepeatButton Command='{x:Static Slider.DecreaseLarge}' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Height='3' Background='"+accent+"' CornerRadius='2'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb Width='13' Height='16'><Thumb.Template><ControlTemplate TargetType='Thumb'><Border Width='12' Height='12' CornerRadius='6' Background='"+thumb+"' BorderBrush='"+accent+"' BorderThickness='1'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='{x:Static Slider.IncreaseLarge}' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Height='3' Background='"+track+"' CornerRadius='2'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate>";
  slider.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse(xaml);var save=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};save.Tick+=(s,e)=>{save.Stop();Save();RuntimeManager.Log("window-pet","slider width="+Win.Width+" height="+Win.Height);};slider.ValueChanged+=(s,e)=>{Win.Width=400*slider.Value/100;Win.Height=560*slider.Value/100;Clamp();label.Text="大小  "+Math.Round(slider.Value)+"%";save.Stop();save.Start();};panel.Children.Add(slider);var host=new MenuItem{Header=panel,StaysOpenOnClick=true,Focusable=false,Foreground=ink,Padding=new Thickness(12,5,12,8)};host.Background=Brushes.Transparent;host.Template=template;return host;}
 static void Scale(double f){Win.Width=Math.Max(240,Math.Min(720,Win.Width*f));Win.Height=Math.Max(320,Math.Min(1000,Win.Height*f));Clamp();Save();RuntimeManager.Log("window-pet","scale width="+Win.Width+" height="+Win.Height);}
 static void Clamp(){var handle=new WindowInteropHelper(Win).Handle;if(handle==IntPtr.Zero)return;var area=Forms.Screen.FromHandle(handle).WorkingArea;var source=HwndSource.FromHwnd(handle);var transform=source.CompositionTarget.TransformFromDevice;var a=transform.Transform(new Point(area.Left,area.Top));var z=transform.Transform(new Point(area.Right,area.Bottom));Win.Width=Math.Min(Win.Width,z.X-a.X);Win.Height=Math.Min(Win.Height,z.Y-a.Y);Win.Left=Math.Max(a.X,Math.Min(Win.Left,z.X-Win.Width));Win.Top=Math.Max(a.Y,Math.Min(Win.Top,z.Y-Win.Height));}
 static void Restore(){try{var p=RuntimeManager.Read(Path.Combine(RuntimeManager.Data,"pet-window.json"));Win.WindowStartupLocation=WindowStartupLocation.Manual;Win.Width=Math.Max(240,Math.Min(720,Convert.ToDouble(p["width"])));Win.Height=Math.Max(320,Math.Min(1000,Convert.ToDouble(p["height"])));Win.Left=Convert.ToDouble(p["left"]);Win.Top=Convert.ToDouble(p["top"]);Win.Topmost=(bool)p["topmost"];}catch{}Win.ContentRendered+=(s,e)=>Clamp();}
 static void Save(){if(!Pet)return;try{Directory.CreateDirectory(RuntimeManager.Data);string path=Path.Combine(RuntimeManager.Data,"pet-window.json"),tmp=path+".tmp";File.WriteAllText(tmp,RuntimeManager.Json.Serialize(new{left=Win.Left,top=Win.Top,width=Win.Width,height=Win.Height,topmost=Win.Topmost}));if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}catch(Exception e){RuntimeManager.Log("window-pet","position-save "+e.GetType().Name);}}
